const https = require('https');

const RICHMENU_PNG = Buffer.from('', 'base64');

function lineRequest(method, path, body, isBuffer) {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: isBuffer ? 'api-data.line.me' : 'api.line.me',
      path,
      method,
      headers: {
        Authorization: `Bearer ${process.env.LINE_CHANNEL_ACCESS_TOKEN}`,
        ...(isBuffer
          ? { 'Content-Type': 'image/png', 'Content-Length': body.length }
          : { 'Content-Type': 'application/json' }),
      },
    };
    const req = https.request(options, res => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        const text = Buffer.concat(chunks).toString();
        try { resolve({ status: res.statusCode, body: JSON.parse(text) }); }
        catch { resolve({ status: res.statusCode, body: text }); }
      });
    });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

module.exports = async function handler(req, res) {
  const token = req.query.token;
  if (token !== process.env.DASHBOARD_TOKEN) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  try {
    const menuDef = {
      size: { width: 2500, height: 843 },
      selected: true,
      name: 'EmmArk 主選單',
      chatBarText: '功能選單',
      areas: [
        { bounds: { x: 0,    y: 0,   width: 625, height: 421 }, action: { type: 'message', text: '今天' } },
        { bounds: { x: 625,  y: 0,   width: 625, height: 421 }, action: { type: 'message', text: '本週' } },
        { bounds: { x: 1250, y: 0,   width: 625, height: 421 }, action: { type: 'message', text: '日曆' } },
        { bounds: { x: 1875, y: 0,   width: 625, height: 421 }, action: { type: 'message', text: '筆記' } },
        { bounds: { x: 0,    y: 421, width: 625, height: 422 }, action: { type: 'message', text: '專案' } },
        { bounds: { x: 625,  y: 421, width: 625, height: 422 }, action: { type: 'message', text: '服事表' } },
        { bounds: { x: 1250, y: 421, width: 625, height: 422 }, action: { type: 'message', text: '指令' } },
        { bounds: { x: 1875, y: 421, width: 625, height: 422 }, action: { type: 'uri', uri: `https://emmask-secret.vercel.app?token=${process.env.DASHBOARD_TOKEN}`, label: 'Dashboard' } },
      ],
    };

    const createRes = await lineRequest('POST', '/v2/bot/richmenu', Buffer.from(JSON.stringify(menuDef)));
    if (createRes.status !== 200) throw new Error(`Create failed: ${JSON.stringify(createRes.body)}`);
    const richMenuId = createRes.body.richMenuId;

    const uploadRes = await lineRequest('POST', `/v2/bot/richmenu/${richMenuId}/content`, RICHMENU_PNG, true);
    if (uploadRes.status !== 200) throw new Error(`Upload failed: ${JSON.stringify(uploadRes.body)}`);

    const defaultRes = await lineRequest('POST', `/v2/bot/user/all/richmenu/${richMenuId}`, null);
    if (defaultRes.status !== 200) throw new Error(`Set default failed: ${JSON.stringify(defaultRes.body)}`);

    return res.status(200).json({ ok: true, richMenuId, message: '圖文選單設定完成！重新整理 LINE 即可看到。' });
  } catch (err) {
    console.error('Setup richmenu error:', err);
    return res.status(500).json({ error: err.message });
  }
};
